CREATE OR REPLACE FUNCTION public.report_session_tech_issue(p_booking_id uuid, p_issue_type text, p_detail text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_booking public.bookings%rowtype;
  v_existing public.session_tech_issue_reports%rowtype;
  v_now timestamptz := pg_catalog.now();
  v_issue_type text := pg_catalog.btrim(coalesce(p_issue_type, ''));
  v_detail text := nullif(pg_catalog.btrim(coalesce(p_detail, '')), '');
  v_role text;
  v_evidence jsonb;
  v_end_reason text;
begin
  if v_actor_id is null or p_booking_id is null then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'not_participant');
  end if;
  if v_issue_type not in (
    'cannot_hear_partner', 'partner_cannot_hear_me',
    'cannot_see_partner', 'partner_cannot_see_me',
    'connection_unstable', 'counterpart_absent', 'other'
  ) or (v_detail is not null and pg_catalog.char_length(v_detail) > 300) then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'invalid_issue');
  end if;

  select * into v_booking from public.bookings
   where id = p_booking_id
     and (learner_id = v_actor_id or partner_user_id = v_actor_id)
   for update;
  if not found then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'not_participant');
  end if;
  v_role := case when v_booking.learner_id = v_actor_id then 'learner' else 'partner' end;

  select * into v_existing from public.session_tech_issue_reports
   where booking_id = p_booking_id and reporter_user_id = v_actor_id;
  if found then
    return pg_catalog.jsonb_build_object(
      'success', true, 'decision', v_existing.decision,
      'issue_type', v_existing.issue_type, 'already_reported', true,
      'refunded', v_booking.ticket_refunded,
      'partner_rewarded', v_booking.partner_rewarded
    );
  end if;

  if (v_booking.status = 'cancelled'
      and coalesce(v_booking.end_reason, '') not in (
        'tech_issue_review', 'partner_no_show_review', 'learner_no_show_review'
      ))
     or v_booking.end_reason in ('user_cancelled_early', 'user_cancelled_late') then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'booking_cancelled');
  end if;
  if v_booking.status = 'tech_issue' and v_booking.end_reason = 'tech_issue' then
    return pg_catalog.jsonb_build_object(
      'success', true, 'decision', 'approved', 'already_reported', true,
      'refunded', v_booking.ticket_refunded,
      'partner_rewarded', v_booking.partner_rewarded
    );
  end if;
  if v_booking.ticket_refunded is true then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'already_refunded');
  end if;
  -- A second participant can add their own report while review is pending.
  if not (v_booking.status = 'confirmed'
          and v_booking.ended_at is null
          and v_booking.completed_at is null
          and nullif(pg_catalog.btrim(v_booking.end_reason), '') is null)
     and not (v_booking.status = 'cancelled'
              and v_booking.end_reason in (
                'tech_issue_review', 'partner_no_show_review', 'learner_no_show_review'
              )) then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'booking_terminal');
  end if;
  if v_booking.scheduled_at is null
     or v_now < v_booking.scheduled_at - interval '5 minutes'
     or v_now > v_booking.scheduled_at + interval '10 minutes' then
    return pg_catalog.jsonb_build_object(
      'success', false, 'code', 'tech_issue_window_closed',
      'message', '湲곗닠 臾몄젣 ?먮룞 泥섎━ 媛???쒓컙???꾨떃?덈떎. ?꾩????꾩슂?섎㈃ 臾몄쓽??二쇱꽭??'
    );
  end if;

  select pg_catalog.jsonb_build_object(
    'learner_room_entered', count(*) filter (
      where event_type = 'room_entered' and actor_user_id = v_booking.learner_id),
    'partner_room_entered', count(*) filter (
      where event_type = 'room_entered' and actor_user_id = v_booking.partner_user_id),
    'learner_media_connected', count(*) filter (
      where event_type = 'media_connected' and actor_user_id = v_booking.learner_id),
    'partner_media_connected', count(*) filter (
      where event_type = 'media_connected' and actor_user_id = v_booking.partner_user_id)
  ) into v_evidence
  from public.session_events where booking_id = p_booking_id
    and event_type in ('room_entered', 'media_connected');

  -- Review is deliberately conservative: 048 has no verifiable failed-media
  -- event, and an absent best-effort success event is not failure evidence.
  v_end_reason := case
    when v_booking.status = 'cancelled' then v_booking.end_reason
    when v_issue_type = 'counterpart_absent' and v_role = 'learner'
      then 'partner_no_show_review'
    when v_issue_type = 'counterpart_absent' and v_role = 'partner'
      then 'learner_no_show_review'
    else 'tech_issue_review'
  end;

  insert into public.session_tech_issue_reports (
    booking_id, reporter_user_id, reporter_role, issue_type, detail,
    reported_at, scheduled_at, decision, evidence
  ) values (
    p_booking_id, v_actor_id, v_role, v_issue_type, v_detail,
    v_now, v_booking.scheduled_at, 'manual_review', v_evidence
  );

  if v_booking.status = 'confirmed' then
    -- A cancelled booking is terminal for room entry and cannot be rewarded
    -- by the normal 045 completion RPC while review is pending.
    -- completed_at stays null because this was not a completed conversation.
    update public.bookings
       set status = 'cancelled', end_reason = v_end_reason,
           ended_at = v_now, updated_at = v_now
     where id = p_booking_id and status = 'confirmed'
       and ended_at is null and completed_at is null
       and nullif(pg_catalog.btrim(end_reason), '') is null;
    if not found then
      raise exception 'Booking changed while reporting a tech issue.' using errcode = '40001';
    end if;
  end if;

  return pg_catalog.jsonb_build_object(
    'success', true, 'decision', 'manual_review',
    'issue_type', v_issue_type, 'end_reason', v_end_reason,
    'refunded', false, 'partner_rewarded', false,
    'no_show_candidate', v_issue_type = 'counterpart_absent'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_tech_issue_report(p_report_id uuid, p_refund_user boolean, p_reward_partner boolean, p_resolution_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_admin_id uuid := auth.uid();
  v_reason text := pg_catalog.btrim(coalesce(p_resolution_reason, ''));
  v_booking_id uuid;
  v_booking public.bookings%rowtype;
  v_report public.session_tech_issue_reports%rowtype;
  v_allocation public.ticket_allocations%rowtype;
  v_lot public.ticket_lots%rowtype;
  v_ticket_count integer;
  v_partner_points integer;
  v_decision text;
  v_end_reason text;
  v_resolved_count integer;
begin
  if v_admin_id is null or not public.dayo_is_admin() then
    raise exception 'Admin access is required.' using errcode = '42501';
  end if;
  if p_report_id is null or p_refund_user is null or p_reward_partner is null
     or v_reason = '' or pg_catalog.char_length(v_reason) > 1000 then
    raise exception 'Report, both decisions, and a reason (1-1000 characters) are required.'
      using errcode = '22023';
  end if;

  -- 060 reporter flow locks booking before touching its report. Resolve in
  -- the same order to avoid a reporter/admin deadlock. Booking lock also
  -- serializes resolutions initiated from either participant's report row.
  select booking_id into v_booking_id
    from public.session_tech_issue_reports where id = p_report_id;
  if not found then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'report_not_found');
  end if;
  select * into v_booking from public.bookings
   where id = v_booking_id for update;
  if not found then
    raise exception 'Technical incident booking is missing.' using errcode = '23514';
  end if;
  select * into v_report from public.session_tech_issue_reports
   where id = p_report_id and booking_id = v_booking_id for update;
  if not found then
    raise exception 'Technical incident changed during resolution.' using errcode = '40001';
  end if;
  if v_report.decision <> 'manual_review'
     or exists (
       select 1 from public.session_tech_issue_reports
        where booking_id = v_booking_id and decision <> 'manual_review'
     ) then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'already_resolved');
  end if;
  if v_booking.status is distinct from 'cancelled'
     or v_booking.end_reason not in (
       'tech_issue_review', 'partner_no_show_review', 'learner_no_show_review'
     ) or v_booking.ended_at is null or v_booking.completed_at is not null then
    return pg_catalog.jsonb_build_object('success', false, 'code', 'booking_not_in_review');
  end if;
  if v_booking.ticket_refunded is distinct from false
     or v_booking.partner_rewarded is distinct from false then
    raise exception 'Booking has already been refunded or rewarded.' using errcode = '23514';
  end if;

  select * into v_allocation from public.ticket_allocations
   where booking_id = v_booking_id for update;
  if found then
    if v_allocation.quantity is distinct from 1 or v_allocation.refunded_at is not null
       or v_allocation.refund_reason is not null then
      raise exception 'Ticket allocation is already refunded or inconsistent.'
        using errcode = '23514';
    end if;
  elsif p_refund_user then
    raise exception 'Cannot refund a booking without its original allocation.'
      using errcode = '23514';
  end if;

  if p_refund_user then
    if v_booking.ticket_deducted is distinct from true then
      raise exception 'Booking has no deducted ticket.' using errcode = '23514';
    end if;
    -- Match 055-057 lock order: booking, allocation, learner profile, lot.
    perform 1 from public.profiles where id = v_booking.learner_id for update;
    if not found then
      raise exception 'Learner profile is missing.' using errcode = 'P0002';
    end if;
    select * into v_lot from public.ticket_lots
     where id = v_allocation.ticket_lot_id for update;
    if not found or v_lot.user_id is distinct from v_booking.learner_id
       or v_lot.quantity_remaining >= v_lot.quantity_issued then
      raise exception 'Original ticket lot cannot be restored.' using errcode = '23514';
    end if;
    update public.ticket_lots
       set quantity_remaining = quantity_remaining + 1,
           updated_at = pg_catalog.now()
     where id = v_lot.id and quantity_remaining < quantity_issued;
    if not found then
      raise exception 'Ticket lot changed during resolution.' using errcode = '40001';
    end if;
    update public.ticket_allocations
       set refunded_at = pg_catalog.now(),
           refund_reason = 'tech_issue_manual_approved'
     where id = v_allocation.id and refunded_at is null;
    if not found then
      raise exception 'Allocation changed during resolution.' using errcode = '40001';
    end if;
    -- The original expires_at is untouched; an already-expired lot does not
    -- become a newly usable ticket when its quantity is restored.
    v_ticket_count := public.refresh_ticket_balance_cache(v_booking.learner_id);
  end if;

  if p_reward_partner then
    if v_booking.partner_user_id is null then
      raise exception 'Booking partner is missing.' using errcode = '23514';
    end if;
    select point_balance into v_partner_points from public.profiles
     where id = v_booking.partner_user_id and role = 'partner' for update;
    if not found then
      raise exception 'Partner profile is missing.' using errcode = 'P0002';
    end if;
    update public.profiles
       set point_balance = coalesce(point_balance, 0) + 6000,
           updated_at = pg_catalog.now()
     where id = v_booking.partner_user_id and role = 'partner'
     returning point_balance into v_partner_points;
    if not found then
      raise exception 'Partner reward changed during resolution.' using errcode = '40001';
    end if;
  end if;

  v_decision := case when p_refund_user or p_reward_partner then 'approved' else 'rejected' end;
  v_end_reason := case
    when v_booking.end_reason = 'partner_no_show_review' then 'partner_no_show_resolved'
    when v_booking.end_reason = 'learner_no_show_review' then 'learner_no_show_resolved'
    when v_decision = 'approved' then 'tech_issue_approved'
    else 'tech_issue_rejected'
  end;
  -- Resolution changes the financial flags and reason, never the cancelled
  -- terminal status or completed_at of this non-completed conversation.
  update public.bookings
     set ticket_refunded = p_refund_user,
         partner_rewarded = p_reward_partner,
         end_reason = v_end_reason,
         updated_at = pg_catalog.now()
   where id = v_booking_id and status = 'cancelled'
     and end_reason = v_booking.end_reason
     and ticket_refunded = false and partner_rewarded = false;
  if not found then
    raise exception 'Booking changed during resolution.' using errcode = '40001';
  end if;

  -- Resolve both participant reports together: a second report ID cannot
  -- later award the same booking a second ticket or another 6,000P.
  update public.session_tech_issue_reports
     set decision = v_decision,
         user_refund_decision = p_refund_user,
         partner_reward_decision = p_reward_partner,
         resolution_reason = v_reason,
         resolved_by = v_admin_id,
         resolved_at = pg_catalog.now()
   where booking_id = v_booking_id and decision = 'manual_review';
  get diagnostics v_resolved_count = row_count;
  if v_resolved_count < 1 then
    raise exception 'No pending report remained for resolution.' using errcode = '40001';
  end if;

  return pg_catalog.jsonb_build_object(
    'success', true, 'booking_id', v_booking_id,
    'decision', v_decision, 'user_refunded', p_refund_user,
    'partner_rewarded', p_reward_partner,
    'ticket_count', v_ticket_count, 'partner_points', v_partner_points,
    'end_reason', v_end_reason, 'reports_resolved', v_resolved_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.upsert_session_transcript(p_booking_id uuid, p_transcript jsonb, p_started_at timestamp with time zone, p_ended_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor_id uuid := auth.uid();
  v_learner_id uuid;
  v_partner_profile_id uuid;
  v_partner_user_id uuid;
  v_scheduled_at timestamptz;
  v_session_window_start timestamptz;
  v_session_window_end timestamptz;
  v_participant_role text;
  v_clean_transcript jsonb;
  v_item jsonb;
  v_item_timestamp timestamptz;
  v_session_log_id uuid;
begin
  if v_actor_id is null then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'code', 'auth_required',
      'message', '濡쒓렇?몄씠 ?꾩슂?⑸땲??'
    );
  end if;

  if p_booking_id is null then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'code', 'invalid_booking_id',
      'message', '?덉빟 ID媛 ?꾩슂?⑸땲??'
    );
  end if;

  select bookings.learner_id, bookings.partner_id, bookings.partner_user_id, bookings.scheduled_at
    into v_learner_id, v_partner_profile_id, v_partner_user_id, v_scheduled_at
    from public.bookings
   where bookings.id = p_booking_id;

  if not found then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'code', 'booking_not_found',
      'message', '?덉빟??李얠쓣 ???놁뒿?덈떎.'
    );
  end if;

  if v_learner_id is null or v_partner_profile_id is null or v_partner_user_id is null then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'code', 'booking_identity_incomplete',
      'message', '?덉빟 李몄뿬???뺣낫媛 ?꾩쟾?섏? ?딆뒿?덈떎.'
    );
  end if;

  if v_actor_id = v_learner_id then
    v_participant_role := 'learner';
  elsif v_actor_id = v_partner_user_id then
    v_participant_role := 'partner';
  else
    return pg_catalog.jsonb_build_object(
      'success', false,
      'code', 'not_booking_participant',
      'message', '???덉빟??李몄뿬?먮쭔 ???湲곕줉????ν븷 ???덉뒿?덈떎.'
    );
  end if;

  if p_transcript is null or pg_catalog.jsonb_typeof(p_transcript) <> 'array' then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'code', 'invalid_transcript',
      'message', '???湲곕줉? JSON 諛곗뿴?댁뼱???⑸땲??'
    );
  end if;

  if pg_catalog.jsonb_array_length(p_transcript) > 1000
     or pg_catalog.octet_length(p_transcript::pg_catalog.text) > 1048576 then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'code', 'transcript_too_large',
      'message', '???湲곕줉 ?ш린 ?쒗븳??珥덇낵?덉뒿?덈떎.'
    );
  end if;

  v_session_window_start := v_scheduled_at - interval '5 minutes';
  v_session_window_end := v_scheduled_at + interval '35 minutes';

  if v_scheduled_at is null
     or p_started_at is null
     or p_ended_at is null
     or p_ended_at < p_started_at
     or p_started_at < v_session_window_start
     or p_started_at > v_session_window_end
     or p_ended_at < v_session_window_start
     or p_ended_at > v_session_window_end then
    return pg_catalog.jsonb_build_object(
      'success', false,
      'code', 'invalid_session_window',
      'message', '?몄뀡 ?쒖옉/醫낅즺 ?쒓컖???뺤씤??二쇱꽭??'
    );
  end if;

  -- Malformed/out-of-window rows are omitted. Missing or invalid timestamps
  -- are never inferred or clamped, and browser speaker labels never determine
  -- participant identity.
  v_clean_transcript := '[]'::pg_catalog.jsonb;
  for v_item in
    select items.item
      from pg_catalog.jsonb_array_elements(p_transcript) with ordinality as items(item, ordinality)
     order by items.ordinality
  loop
    if pg_catalog.jsonb_typeof(v_item) <> 'object'
       or pg_catalog.jsonb_typeof(v_item -> 'speaker') <> 'string'
       or pg_catalog.lower(pg_catalog.btrim(v_item ->> 'speaker')) <> v_participant_role
       or pg_catalog.jsonb_typeof(v_item -> 'text') <> 'string'
       or pg_catalog.char_length(pg_catalog.btrim(v_item ->> 'text')) not between 1 and 4000
       or pg_catalog.jsonb_typeof(v_item -> 'timestamp') <> 'string'
       or pg_catalog.btrim(v_item ->> 'timestamp') !~
         '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$' then
      continue;
    end if;

    begin
      v_item_timestamp := (v_item ->> 'timestamp')::pg_catalog.timestamptz;
    exception when others then
      continue;
    end;

    if v_item_timestamp < v_session_window_start
       or v_item_timestamp > v_session_window_end then
      continue;
    end if;

    v_clean_transcript := v_clean_transcript || pg_catalog.jsonb_build_array(v_item);
  end loop;

  insert into public.session_logs (
    booking_id,
    participant_id,
    participant_role,
    learner_id,
    partner_id,
    user_id,
    room_id,
    transcript,
    started_at,
    ended_at,
    updated_at
  ) values (
    p_booking_id,
    v_actor_id,
    v_participant_role,
    v_learner_id,
    v_partner_profile_id,
    v_actor_id,
    p_booking_id::pg_catalog.text,
    v_clean_transcript,
    p_started_at,
    p_ended_at,
    pg_catalog.now()
  )
  on conflict (booking_id, participant_role)
    where booking_id is not null and participant_role is not null
  do update set
    participant_id = excluded.participant_id,
    learner_id = excluded.learner_id,
    partner_id = excluded.partner_id,
    user_id = excluded.user_id,
    room_id = excluded.room_id,
    transcript = excluded.transcript,
    started_at = excluded.started_at,
    ended_at = excluded.ended_at,
    updated_at = pg_catalog.now()
  returning session_logs.id into v_session_log_id;

  return pg_catalog.jsonb_build_object(
    'success', true,
    'session_log_id', v_session_log_id,
    'booking_id', p_booking_id,
    'participant_id', v_actor_id,
    'participant_role', v_participant_role,
    'partner_id', v_partner_profile_id,
    'item_count', pg_catalog.jsonb_array_length(v_clean_transcript)
  );
end
$function$

CREATE OR REPLACE FUNCTION public.get_admin_partner_availability(p_partner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_now timestamptz := clock_timestamp();
  v_today date := (v_now at time zone 'Asia/Seoul')::date;
  v_available jsonb;
  v_slots jsonb;
  v_languages text[];
begin
  if auth.uid() is null or not public.dayo_is_admin() then
    raise exception 'Admin access required' using errcode='42501';
  end if;
  if p_partner_id is null or not exists (
    select 1 from public.profiles where id=p_partner_id and role='partner'
  ) then raise exception 'Partner profile not found' using errcode='P0002'; end if;
  v_available := public.get_booking_calendar_slots(array[p_partner_id]);
  select conversation_languages into v_languages from public.partner_capabilities
    where partner_id=p_partner_id;
  select coalesce(jsonb_agg(row order by starts_at,status),'[]'::jsonb) into v_slots
  from (
    select jsonb_build_object('id',x->>'id','slot_time',x->>'slot_time','status','available') row,
      public.availability_kst_start(x->>'slot_time') starts_at, 'available' status
    from jsonb_array_elements(v_available) x
    where public.availability_kst_start(x->>'slot_time') >= v_now + interval '4 hours'
      and coalesce(v_languages && array['en','es','fr','ko']::text[],false)
      and not exists (select 1 from public.bookings b where b.status='confirmed'
        and (b.slot_id=(x->>'id')::uuid or (b.partner_id=p_partner_id
          and b.scheduled_at=public.availability_kst_start(x->>'slot_time'))))
    union all
    select jsonb_build_object('id',s.id,'slot_time',s.slot_time,'status','booked'),
      public.availability_kst_start(s.slot_time), 'booked'
    from public.availability_slots s
    where s.partner_id=p_partner_id
      and public.availability_kst_start(s.slot_time)>v_now
      and (public.availability_kst_start(s.slot_time) at time zone 'Asia/Seoul')::date between v_today and v_today+29
      and (s.status='booked' or exists (select 1 from public.bookings b where b.status='confirmed'
        and (b.slot_id=s.id or (b.partner_id=p_partner_id and b.scheduled_at=public.availability_kst_start(s.slot_time)))))
  ) effective;
  return jsonb_build_object('partner_id',p_partner_id,'start',v_today,'end',v_today+29,
    'as_of',v_now,'min_lead_hours',4,'capability_configured',coalesce(v_languages && array['en','es','fr','ko']::text[],false),
    'slots',v_slots);
end;
$function$
